43	public class DataTypeJsonSerDe {
44	  private static final ObjectMapper OBJECT_MAPPER =
45	      new ObjectMapper()
46	          .registerModule(
47	              new SimpleModule().addSerializer(StructType.class, new StructTypeSerializer()));
48	
49	  private DataTypeJsonSerDe() {}
